#include <stdio.h>
#include <string.h>

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("EMPTY\n");
        return 0;
    }
    char *str = argv[1];
    int len = strlen(str);
    if (len > 1024) {
        len = 1024;
    }
    int i = 0;
    int j = 0;
    char out[1024] = {0};
    int started = 0;
    for (i = 0; i < len; i++) {
        if (str[i] != ' ' && str[i] != '\t' && str[i] != '\n' && str[i] != '\r' && str[i] != '\v' && str[i] != '\f') {
            started = 1;
            out[j++] = str[i];
        } else if (started) {
            out[j++] = ' ';
        }
    }
    out[j] = '\0';
    printf("%s\n", out);
    return 0;
}
